// The 100-meal "Insta" batch for the coach's Meal Library
// (src/lib/instaMealsAU.js, generated by scripts/genInstaMealsAU.mjs).
// The numbers must be exact: every ingredient line is re-derived here from
// the Food Library entry it names, and every meal total must be the sum of
// its lines.
import { describe, expect, it } from "vitest";
import { INSTA_MEALS_AU } from "./instaMealsAU";
import { FITNESS_MEALS_AU } from "./fitnessMealsAU";
import { FOOD_DATABASE } from "./foodDatabase";

const byId = Object.fromEntries(FOOD_DATABASE.map((f) => [f.id, f]));
const r1 = (n) => Math.round(n * 10) / 10;

describe("Insta meal batch", () => {
  it("has 100 meals: 34 breakfasts, 33 lunches, 33 dinners, unique ids and names", () => {
    expect(INSTA_MEALS_AU).toHaveLength(100);
    const count = (t) => INSTA_MEALS_AU.filter((m) => m.mealTypes[0] === t).length;
    expect([count("Breakfast"), count("Lunch"), count("Dinner")]).toEqual([34, 33, 33]);
    expect(new Set(INSTA_MEALS_AU.map((m) => m.id)).size).toBe(100);
    const names = INSTA_MEALS_AU.map((m) => m.name.toLowerCase());
    expect(new Set(names).size).toBe(100);
    const existing = new Set(FITNESS_MEALS_AU.map((m) => m.name.toLowerCase()));
    expect(names.filter((n) => existing.has(n))).toEqual([]);
    expect(new Set(FITNESS_MEALS_AU.map((m) => m.id)).has(INSTA_MEALS_AU[0].id)).toBe(false);
  });

  it("every ingredient line matches its Food Library entry scaled to the stated grams", () => {
    for (const meal of INSTA_MEALS_AU) {
      for (const ing of meal.ingredients) {
        const f = byId[ing.baseFoodId];
        expect(f, `${meal.name}: ${ing.baseFoodId}`).toBeTruthy();
        const k = ing.grams / f.per;
        expect(ing.cals).toBe(Math.round(f.cals * k));
        expect(ing.protein).toBe(r1(f.protein * k));
        expect(ing.carbs).toBe(r1(f.carbs * k));
        expect(ing.fat).toBe(r1(f.fat * k));
        expect(ing.grams).toBeGreaterThan(0);
      }
    }
  });

  it("every meal's totals are exactly the sum of its ingredient lines", () => {
    for (const meal of INSTA_MEALS_AU) {
      const sum = (k) => meal.ingredients.reduce((a, i) => a + i[k], 0);
      expect(meal.cals).toBe(sum("cals"));
      expect(meal.protein).toBe(r1(sum("protein")));
      expect(meal.carbs).toBe(r1(sum("carbs")));
      expect(meal.fat).toBe(r1(sum("fat")));
    }
  });

  it("calories agree with 4/4/9 kcal per gram of protein/carbs/fat to within 8%", () => {
    for (const meal of INSTA_MEALS_AU) {
      const atwater = meal.protein * 4 + meal.carbs * 4 + meal.fat * 9;
      expect(Math.abs(meal.cals - atwater) / meal.cals, meal.name).toBeLessThan(0.08);
    }
  });

  it("is high protein for its calories, as described", () => {
    for (const meal of INSTA_MEALS_AU) {
      const isBreakfast = meal.mealTypes[0] === "Breakfast";
      expect(meal.cals, meal.name).toBeLessThanOrEqual(isBreakfast ? 470 : 570);
      expect(meal.protein, meal.name).toBeGreaterThanOrEqual(isBreakfast ? 26 : 34);
    }
  });

  it("says raw or cooked weight for every meat, fish, rice, pasta and potato line", () => {
    const needsBasis = /chicken breast|chicken thigh|mince|steak|salmon fillet|barramundi|lamb leg|rice,|penne|spaghetti|fettuccine|macaroni|lasagne|vermicelli|ramen|egg noodles|quinoa|potato,|sweet potato/i;
    for (const meal of INSTA_MEALS_AU) {
      for (const ing of meal.ingredients) {
        if (needsBasis.test(ing.name) && !/shaved|gnocchi/i.test(ing.name)) expect(ing.name, meal.name).toMatch(/raw weight|cooked weight|cooked & peeled/);
      }
    }
  });

  it("each meal has numbered steps, and any photo is a free Unsplash image", () => {
    for (const meal of INSTA_MEALS_AU) {
      expect(meal.instructions.startsWith("1. ")).toBe(true);
      if (meal.photoUrl) expect(meal.photoUrl).toMatch(/^https:\/\/images\.unsplash\.com\/photo-/);
    }
  });
});
